tool_input.command:
$repo = "D:\repository\skills\dsh\profiles\web\cordis.patch.yml"
$lines = Get-Content $repo -Encoding utf8
Write-Output "=== repo 版 workflow 归属 preset ==="
for($i=0;$i -lt $lines.Count;$i++){
  if($lines[$i] -match "id: tool-workflow"){
    $owner=""; for($j=$i;$j -ge 0;$j--){ if($lines[$j] -match "id: preset-"){ $owner=$lines[$j].Trim(); break } }
    $dis = if($lines[$i+2] -match 'disabled'){'DISABLED'}else{'enabled'}
    Write-Output "L$($i+1): owner=[$owner] $dis"
  }
}
Write-Output "=== repo preset-standard 块范围(L280 前后) ==="
$s = ($lines | Select-String "id: preset-standard" | Select-Object -First 1)
Write-Output "preset-standard 行: $s"
$lines[276..284] | ForEach-Object { "  $_" }
